 13	Fix a prime power $q=p^t$. Write $\omega=e^{2\pi i/p}$, and let $\tr:\F_q\to\F_p$ denote the finite-field trace.
 14	
 15	\begin{definition}[Finite field trace]\label{def:ff-trace}
 16		\lean{MIPStarRE.LDT.Preliminaries.ffTrace}
 17		\leanok
 18		The finite-field trace is the map $\tr:\F_q\to\F_p$ defined by
 19		\[
 20			\tr[x] = \sum_{\ell=0}^{t-1} x^{p^\ell}.
 21		\]
 22	\end{definition}
 23	
 24	\begin{lemma}\label{prop:fourier-fact-scalar}
 25		\lean{MIPStarRE.LDT.Preliminaries.fourier_fact_scalar}
 26		\leanok
 27		\uses{def:ff-trace}
 28		Let $a \in \F_q$. Then
 29		\begin{equation*}
 30			\E_{\bx \sim \F_q} \omega^{\tr[\bx \cdot a]}
 31			= \left\{\begin{array}{rl}
 32				1 & \text{if $a = 0$}, \\
 33				0 & \text{otherwise}.
 34			\end{array}\right.
 35		\end{equation*}
 36	\end{lemma}
 37	\begin{proof}
 38		\leanok
 39		If $a=0$, then $\tr[\bx\cdot a]=0$ for every $\bx$, so the average is $1$. If $a\neq 0$, choose $y \in \F_q$ such that $\tr[a\cdot y]\neq 0$, and set
 40		\[
 41			C=\E_{\bx \sim \F_q} \omega^{\tr[\bx \cdot a]}.
 42		\]
 43		Translation invariance of the uniform distribution gives
 44		\[
 45			C=\E_{\bx \sim \F_q} \omega^{\tr[(\bx+y)\cdot a]}
 46			= C \cdot \omega^{\tr[y\cdot a]}.
 47		\]
 48		Since $\omega^{\tr[y\cdot a]}\neq 1$, it follows that $C=0$.
 49	\end{proof}
 50	
 51	\begin{lemma}\label{prop:fourier-fact-vector}
 52		\lean{MIPStarRE.LDT.Preliminaries.fourier_fact_vector}
 53		\leanok
 54		\uses{def:ff-trace, prop:fourier-fact-scalar}
 55		Let $v \in \F_q^m$. Then
 56		\begin{equation*}
 57			\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
 58			= \left\{\begin{array}{rl}
 59				1 & \text{if $v = 0$}, \\
 60				0 & \text{otherwise}.
 61			\end{array}\right.
 62		\end{equation*}
 63	\end{lemma}
 64	\begin{proof}
 65		\leanok
 66		By linearity of the trace and independence of the coordinates,
 67		\[
 68			\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
 69			= \prod_{i=1}^m \E_{\bu_i \sim \F_q} \omega^{\tr[\bu_i \cdot v_i]}.
 70		\]
 71		Proposition~\ref{prop:fourier-fact-scalar} shows that the $i$-th factor is $1$ when $v_i=0$ and $0$ otherwise, so the product is $1$ exactly when $v=0$.
 72	\end{proof}
