 74	\begin{lemma}[Fourier orthogonality for a finite index set]
 75	\label{lem:fourier-fact-finite-index}
 76		\lean{MIPStarRE.LDT.Preliminaries.expect_ffChar_sum_mul}
 77		\lean{MIPStarRE.LDT.Preliminaries.sum_ffChar_sum_mul}
 78		\leanok
 79		\uses{def:ff-trace}
 80		This auxiliary lemma is a finite reindexing of
 81		Lemma~\ref{prop:fourier-fact-vector}, not a separate statement of the paper.
 82		Let $F$ be a finite field of prime characteristic $p$, with its canonical
 83		$\F_p$-algebra structure, and put $q=|F|$. Let $I$ be a finite index set,
 84		possibly empty, and let $v\in F^I$. Write
 85		$\chi(x)=\omega^{\tr[x]}$, where $\tr:F\to\F_p$ is the field trace.
 86		Then the uniform expectation and the unnormalized sum satisfy
 87		\[
 88			\E_{u\in F^I}\chi\Bigl(\sum_{i\in I}u_i v_i\Bigr)
 89			=\begin{cases}1&v=0,\\0&v\ne0,\end{cases}
 90			\qquad
 91			\sum_{u\in F^I}\chi\Bigl(\sum_{i\in I}u_i v_i\Bigr)
 92			=\begin{cases}q^{|I|}&v=0,\\0&v\ne0.\end{cases}
 93		\]
 94	\end{lemma}
 95	\begin{proof}
 96		\leanok
 97		\uses{prop:fourier-fact-vector}
 98		Choose a bijection from $I$ to $\{0,\ldots,|I|-1\}$, interpreted as
 99		the empty set when $I$ is empty. Reindexing both vectors preserves their
100		dot product, the uniform expectation, and the condition $v=0$.
101		Lemma~\ref{prop:fourier-fact-vector} therefore gives the first identity.
102		Multiplying by $|F^I|=q^{|I|}$ gives the second.
103	\end{proof}
