105	\begin{definition}[Low individual degree polynomials]\label{def:polyfunc}
106		\lean{MIPStarRE.LDT.Preliminaries.polyFunc, MIPStarRE.LDT.Polynomial}
107		\leanok
108		Let $\polyfunc{m}{q}{d}$ be the set of polynomials $g \in \F_q[x_1,\dots,x_m]$ whose degree in each variable is at most $d$, viewed as functions $\F_q^m \to \F_q$ via evaluation. (Over finite fields, distinct low-degree polynomials can induce the same function; we identify elements of $\polyfunc{m}{q}{d}$ with their polynomial representatives, not their functional equivalence classes.)
109	\end{definition}
110	
111	\begin{remark}[Individual-degree convention]\label{rem:individual-degree-convention}
112		Here, ``individual degree $d$'' means degree at most $d$ in each coordinate. In
113		particular,
114		\[
115			\polyfunc{m}{q}{d} \subseteq \polyfunc{m}{q}{d+1}.
116		\]
117	\end{remark}
118	
119	\begin{lemma}[Schwartz--Zippel lemma~\cite{Sch80,Zip79}]\label{lem:schwartz-zippel-total-degree}
120		\lean{MIPStarRE.LDT.Preliminaries.schwartzZippel_totalDegree}
121		\leanok
122		Let $g, h:\F_q^m \rightarrow \F_q$ be two distinct polynomials of total degree~$d$.
123		Then
124		\begin{equation*}
125			\Prb_{\bx \sim \F_q^m}[g(\bx) = h(\bx)] \leq \frac{d}{q}.
126		\end{equation*}
127	\end{lemma}
128	\begin{proof}
129		\leanok
130		Apply the Schwartz--Zippel lemma to the nonzero polynomial $g-h$, which has total degree at most $d$.
131	\end{proof}
132	
133	\begin{lemma}[Schwartz--Zippel for individual degree]\label{lem:schwartz-zippel-individual}
134		\lean{MIPStarRE.LDT.Preliminaries.schwartzZippel_individualDegree}
135		\lean{MIPStarRE.QPBT.polyFunc_eval_collision_le}
136		\leanok
137		\uses{def:polyfunc, lem:schwartz-zippel-total-degree}
138		If $g,h \in \polyfunc{m}{q}{d}$ are distinct, then
139		\[
140			\Prb_{u \sim \F_q^m}[g(u)=h(u)] \le \frac{md}{q}.
141		\]
142	\end{lemma}
143	\begin{proof}
144		\leanok
145		The difference $g-h$ is a nonzero polynomial of total degree at most $md$. Apply Lemma~\ref{lem:schwartz-zippel-total-degree}.
146	\end{proof}
