148	\begin{lemma}[Polynomial agreement bound on coded points]\label{lem:polynomial-agreement-mdq}
149		\lean{MIPStarRE.LDT.Preliminaries.polynomialAgreement_avg_le_mdq}
150		\leanok
151		\uses{lem:schwartz-zippel-individual}
152		Let $g, g' : \mathrm{Polynomial}\,\mathrm{params}$ be two distinct full polynomial outcomes with individual degrees at most $d$. Then
153		\[
154			\E_{u \sim \mathrm{Point}\,\mathrm{params}}\bigl[\mathbf{1}[g(u) = g'(u)]\bigr] \le \frac{md}{q}.
155		\]
156		This packages the $md/q$ loss term used in the \texttt{mainFormal} self-consistency cascade (\texttt{inductive\_step.tex}, lines 119--133) and in \texttt{comMain} (\texttt{commutativity-G.tex}).
157	\end{lemma}
158	\begin{proof}
159		\leanok
160		Transport along the equivalence between coded $\F_q$ points and the underlying scalar function space, then apply Lemma~\ref{lem:schwartz-zippel-individual}.
