163	\begin{lemma}[Axis-line polynomial agreement bound]\label{lem:axis-line-polynomial-agreement-mdq}
164		\lean{MIPStarRE.LDT.Preliminaries.axisLinePolynomialAgreement_avg_eq_scalarDomain, MIPStarRE.LDT.Preliminaries.axisLinePolynomialAgreement_avg_le_mdq}
165		\leanok
166		Let $f,h : \mathrm{AxisLinePolynomial}\,\mathrm{params}$ be two line-polynomial outcomes with distinct underlying polynomials. Then
