177	\begin{definition}[Measurements and submeasurements]\label{def:submeasurement}
178		\lean{MIPStarRE.LDT.SubMeas, MIPStarRE.LDT.Measurement, MIPStarRE.LDT.ProjSubMeas}
179		\leanok
180		Let $\mathcal H$ be a Hilbert space and let $\mathcal A$ be a set of outcomes. A submeasurement on $\mathcal A$ is a family $A=\{A_a\}_{a \in \mathcal A}$ of Hermitian positive semidefinite operators on $\mathcal H$ such that $\sum_a A_a \le I$. It is a measurement when $\sum_a A_a = I$, and it is projective when each $A_a$ is an idempotent projection. (In the Lean formalization, outcome sets are assumed finite throughout.)
181	\end{definition}
182	
183	\begin{definition}[Low-degree polynomial measurements]\label{def:polymeasurements}
184		\lean{MIPStarRE.LDT.SubMeas, MIPStarRE.LDT.Measurement, MIPStarRE.LDT.Polynomial}
185		\leanok
186		\uses{def:polyfunc, def:submeasurement}
187		We write $\polysub{m}{q}{d}$ for the submeasurements indexed by $\polyfunc{m}{q}{d}$, and $\polymeas{m}{q}{d}$ for the corresponding measurements.
188	\end{definition}
