190	\begin{definition}[Post-processing]\label{def:post-processing}
191		\lean{MIPStarRE.LDT.postprocess}
192		\leanok
193		\uses{def:submeasurement}
194		Let $A=\{A_a\}_{a \in \mathcal A}$ be a family of operators and let $f\colon \mathcal A \to \mathcal B$. The post-processed family $A_{[f(a)=b]}$ is defined by
195		\[
196			A_{[f(a)=b]} = \sum_{a\, :\, f(a)=b} A_a.
197		\]
198	\end{definition}
199	
200	\begin{proposition}[Post-processing preserves measurements]\label{prop:post-processing-preserves}
201		\lean{MIPStarRE.LDT.Preliminaries.postprocessPreservesMeasurements, MIPStarRE.Quantum.Submeasurement.postprocess_sum_eq, MIPStarRE.Quantum.Measurement.postprocess}
202		\leanok
203		\uses{def:post-processing, def:submeasurement}
204		Let $A=\{A_a\}_{a \in \mathcal A}$ be a family of operators and let
205		$f\colon \mathcal A \to \mathcal B$. Then
206		\[
207			\sum_a A_a = \sum_b A_{[f(a)=b]}.
208		\]
209		Consequently, if $\{A_a\}$ is a submeasurement, respectively a measurement, then
210		$\{A_{[f(a)=b]}\}$ is again a submeasurement, respectively a measurement.
211	\end{proposition}
212	\begin{proof}
213		\leanok
214		Each $a \in \mathcal A$ contributes exactly once to the right-hand side, namely in
215		the summand indexed by $b=f(a)$.
216	\end{proof}
217	
218	\begin{remark}[Post-processing notation]\label{rem:post-processing-notation}
219		In the notation $A_{[f(a)=b]}$, the measurement outcome is the variable to which
220		the function is applied. For example, if $G=\{G_g\} \in \polysub{m}{q}{d}$ and
221		$u \in \F_q^m$, then
222		\[
223			G_{[g(u)=a]} = \sum_{g\,:\,g(u)=a} G_g.
224		\]
225		Here $g$ is the measurement outcome, and $u$ is the evaluation point.
226	\end{remark}
