228	\begin{definition}[Completion of a submeasurement]\label{def:measurement-completion}
229		\lean{MIPStarRE.LDT.Preliminaries.completeAtOutcome}
230		\leanok
231		\uses{def:submeasurement}
232		Let $A=\{A_a^x\}_{a \in \mathcal A}$ be a submeasurement. Its completion is the measurement $\widehat A$ with outcome set $\widehat{\mathcal A}=\mathcal A \cup \{\bot\}$ given by $\widehat A_a^x=A_a^x$ for $a \in \mathcal A$ and $\widehat A_\bot^x = I-\sum_a A_a^x$.
233	\end{definition}
