109	\end{gather}
110	In addition, because the original strategy is $(3\eps, 3\eps, 3\eps)$-good,
111	\begin{equation*}
112	A^{\mathrm{A},u}_a \otimes I \simeq_{3\eps} I \otimes A^{\mathrm{B},u}_a.
113	\end{equation*}
114	Hence, \Cref{prop:simeq-triangle-inequality} implies that
